INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(18201, 'Jeremiah 14:21', 'Jeremiah', 14, 21, '&nbsp;د خپل نوم د خاطره دې مونږ مۀ پرېږده، او خپل جلالى تخت دې مۀ سپکوه. خپل لوظ دې راپه ياد کړه کوم چې تا مونږ سره کړے دے او هغه مۀ ماتوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18202, 'Jeremiah 14:22', 'Jeremiah', 14, 22, '&nbsp;آيا د نورو قومونو د بُتانو فضول معبودان باران کولے شى څۀ؟ آيا آسمان په خپله باران ورولے شى څۀ؟ نه، بلکې دا تۀ يې، اے مالِکه خُدايه، زمونږ پاکه خُدايه. نو د دې دپاره زمونږ توکل په تا دے، ځکه چې تۀ هغه ذات يې څوک چې دا هر څۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18203, 'Jeremiah 15:1', 'Jeremiah', 15, 1, '&nbsp;بيا مالِک خُدائ ما ته وفرمائيل، ”کۀ چرې موسىٰ او سموئيل هم دلته ودرېدلى وے او ما ته يې د دې خلقو په حقله مِنت زارى کړے وے، نو زما زړۀ به دوئ ته مائل شوے نۀ وو. هغوئ زما د حضور نه وشړه، او پرېږده چې ځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18204, 'Jeremiah 15:2', 'Jeremiah', 15, 2, '&nbsp;او کۀ چرې هغوئ ستا نه تپوس وکړى چې مونږ چرته لاړ شُو؟ هغوئ ته ووايه، چې مالِک خُدائ داسې فرمائى، د کومو خلقو په نصيب کښې چې په وبا مړۀ کېدل دى هغوئ دې په وبا مړۀ شى، د چا په نصيب کښې چې په جنګ کښې مړۀ کېدل دى هغوئ دې په جنګ مړۀ شى، د چا په نصيب کښې چې په لوږه مړۀ کېدل دى هغوئ دې په لوږه مړۀ شى، او د چا په نصيب کښې چې جلاوطنى ده هغه دې جلاوطن کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18205, 'Jeremiah 15:3', 'Jeremiah', 15, 3, '&nbsp;مالِک خُدائ فرمائى چې، زۀ به څلور قسمه تباه کوونکى ورولېږم. تُوره د هغوئ د وژلو دپاره، سپى چې د هغوئ لاشونه راکاږى، ټپوسان چې هغوئ تېر کړى او ځنګلى ځناور چې هغوئ ختم کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18206, 'Jeremiah 15:4', 'Jeremiah', 15, 4, '&nbsp;د يهوداه بادشاه منسى د حزقياه د زوئ په وجه چا چې بد کارونه په يروشلم کښې کړى وُو، زۀ به خپل خلق د دُنيا بادشاهانو دپاره د يرې يو مثال جوړ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18207, 'Jeremiah 15:5', 'Jeremiah', 15, 5, '&nbsp;اے يروشلمه څوک به په تاسو رحم وکړى؟ او څوک به په تاسو وير وکړى؟ ستاسو داسې همدرد نشته چې ستاسو تپوس له راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18208, 'Jeremiah 15:6', 'Jeremiah', 15, 6, '&nbsp;مالِک خُدائ فرمائى چې، تاسو زۀ رد کړے يم، او بار بار مو ما ته شا کړې ده. نو اوس به زۀ خپل لاس ستاسو د بربادۍ دپاره دراوږد کړم، نو په تاسو زۀ نور رحم نۀ شم کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18209, 'Jeremiah 15:7', 'Jeremiah', 15, 7, '&nbsp;زۀ به تاسو، ستاسو د ښارونو په دروازو کښې داسې د يو بل نه جدا کړم لکه څنګه چې غنم او بوس جدا کولے شى. او تاسو نه به ستاسو بچى واخلم کوم چې په تاسو ډېر ګران دى. زۀ به خپل قوم تباه کړم، ځکه چې هغوئ د خپلو خرابو طريقو پرېښودو نه اِنکار کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18210, 'Jeremiah 15:8', 'Jeremiah', 15, 8, '&nbsp;ستاسو په مُلک کښې به کونډې د سمندر په غاړه د شګو نه هم ډيرې وى. په نيمه ورځ به زۀ د ځوانانو په ميندو باندې تباهى راولم. او ناګهانه به په دوئ پرېشانى او دهشت راولم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18211, 'Jeremiah 15:9', 'Jeremiah', 15, 9, '&nbsp;د اوو بچو مور د غم نه بې‌هوشه پرته ده او ساه نۀ شى اخستلے، د هغې د بچو د ژوند رڼا ختمه شوه. هغه رسوا او شرمنده شوې ده. په هغوئ کښې چې څوک پاتې دى هغه به زۀ د دشمنانو په تُوره مړۀ کړم. دا د مالِک خُدائ وينا ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18212, 'Jeremiah 15:10', 'Jeremiah', 15, 10, '&nbsp;نو ما بيا ووئيل چې، کاش چې زۀ د مور نه پېدا شوے هم نۀ وے. زۀ چې چرته هم ځم نو هلته خلق زما مخالف دى او جنګ راسره کوى. نۀ مې چا ته قرض ورکړے دے او نۀ مې د چا نه قرض اخستے دے، خو بيا هم دوئ ټول په ما لعنت وائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18213, 'Jeremiah 15:11', 'Jeremiah', 15, 11, '&nbsp;مالِک خُدائ فرمائى چې، ”په يقين سره به زۀ ستا ښۀ مقصد دپاره خيال وساتم، يرمياه. او په يقين سره ستا دشمنان به ستا نه دا وغواړى چې تۀ د تکليف او مصيبت په وخت کښې د هغوئ دپاره ما ته سوال زارى وکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18214, 'Jeremiah 15:12', 'Jeremiah', 15, 12, '&nbsp;آيا څوک هغه د اوسپنې او د پيتلو نه جوړ شوے سيخ ماتولے شى کوم چې د شمال د خوا نه راځى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18215, 'Jeremiah 15:13', 'Jeremiah', 15, 13, '&nbsp;زۀ به ستاسو مال دولت او خزانې مفتې دشمنانو ته د لوټ کولو دپاره حواله کړم، ځکه دا ستاسو د هغه ګناهونو په وجه چې تاسو په ټول مُلک کښې کړې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18216, 'Jeremiah 15:14', 'Jeremiah', 15, 14, '&nbsp;زۀ به تاسو د دشمنانو په لاس يو داسې مُلک ته په غلامۍ ولېږم چې تاسو ته د هغې هيڅ پته نۀ وى. ځکه چې زما غصه د اور په شان رابله شوې ده او دا به د تل دپاره بليږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18217, 'Jeremiah 15:15', 'Jeremiah', 15, 15, '&nbsp;بيا ما ووئيل چې، ”اے مالِکه خُدايه، تا ته د هر څۀ پته ده، څۀ چې ما سره کيږى. نو راشه او زما مدد وکړه. زما د دشمنانو نه بدل واخله او هغوئ ته دومره صبر مۀ کوه چې زما د وژلو موقع ورته مِلاو شى. ګوره خو ما په خپل ځان دا ټوله بې‌عزتى ستا د خاطره تېره کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18218, 'Jeremiah 15:16', 'Jeremiah', 15, 16, '&nbsp;اے مالِکه، ربُ الافواجه خُدايه، هرکله به چې ستا کلام په ما نازل شو، نو هغه ما وخوړلو، هغۀ ما ته او زما زړۀ ته خوشحالى راکړه، ځکه چې ما پورې ستا نوم تړلے شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18219, 'Jeremiah 15:17', 'Jeremiah', 15, 17, '&nbsp;زۀ د هغه خلقو سره شامل نۀ شوم چې خندا او خوشحالى به يې کوله. زۀ ځان ته کښېناستم ځکه چې ستا لاس په ما وو. او د هغوئ د ګناهونو په وجه زما قهر راوچت شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18220, 'Jeremiah 15:18', 'Jeremiah', 15, 18, '&nbsp;زما درد ولې نۀ ختميږى؟ او زما زخمونه ولې لا علاجه دى او نۀ رغيږى؟ ستا مدد زما دپاره داسې نا باوره شو لکه موسمى لختى، لکه د هغه چينې په شان چې اوچه شوې وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18221, 'Jeremiah 15:19', 'Jeremiah', 15, 19, '&nbsp;نو مالِک خُدائ په جواب کښې ما ته وفرمائيل، ”کۀ تۀ واپس راشې، نو زۀ به تا له بيا خپل مقام درکړم چې تۀ زما خِدمت وکړې. کۀ تۀ د بې‌مطلبه خبرو په ځائ زما قيمتى کلام بيان کړې، نو تۀ به زما پېغمبر يې. دا خلق دې ضرور تا له راشى بلکې تۀ د هغوئ په شان مۀ جوړېږه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18222, 'Jeremiah 15:20', 'Jeremiah', 15, 20, '&nbsp;مالِک خُدائ فرمائى چې، زۀ به تا د دې خلقو په وړاندې د پيتلو قوى دېوال جوړ کړم. هغوئ به ستا خِلاف جنګ کوى، خو هغوئ به تا له شکست نۀ شى درکولے، ځکه چې زۀ تا سره يم چې تا وساتم او خلاصون درکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18223, 'Jeremiah 15:21', 'Jeremiah', 15, 21, '&nbsp;زۀ به تا د شريرانو د لاسونو نه وساتم، او د ظالمانو د زور او لاسونو نه به درله خلاصون درکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18224, 'Jeremiah 16:1', 'Jeremiah', 16, 1, '&nbsp;د مالِک خُدائ کلام په ما نازل شو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18225, 'Jeremiah 16:2', 'Jeremiah', 16, 2, '&nbsp;”دلته وادۀ ونۀ کړې او نۀ زامن او لوڼه پېدا کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18226, 'Jeremiah 16:3', 'Jeremiah', 16, 3, '&nbsp;ځکه چې زۀ مالِک خُدائ دا وايم چې، کوم ماشومان چې دلته پېدا کيږى او هم داسې د هغوئ مور، پلار', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18227, 'Jeremiah 16:4', 'Jeremiah', 16, 4, '&nbsp;چې هغوئ به د سختو بيمارو نه مړۀ شى. او په هغوئ به هيڅ څوک ژړا ونۀ کړى او نۀ به يې ښخ کړى، او د هغوئ لاشونه به په زمکه لکه د سوټو په شان خوارۀ وارۀ پراتۀ وى. او هغوئ به په جنګ او قحط مړۀ شى، او د هغوئ لاشونه به د ټپوسانو، او د ځنګلى ځناورو خوراک شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18228, 'Jeremiah 16:5', 'Jeremiah', 16, 5, '&nbsp;مالِک خُدائ داسې فرمائى چې، هغه کور ته مۀ ورننوځه په کوم کښې چې د مړى ژړا وى، د هغوئ سره ماتم او همدردى مۀ کوه، ځکه چې ما د هغه خلقو نه خپل برکت، مينه او رحم اخوا کړے دے، دا د مالِک خُدائ وينا ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18229, 'Jeremiah 16:6', 'Jeremiah', 16, 6, '&nbsp;مالداره او غريبانان به دواړه په دې مُلک کښې مړۀ شى، هغوئ به نۀ ښخ کړے شى او نۀ به ورباندې ماتم وشى، د هغوئ دوستان به نۀ خپل ځانونه دردمند کړى او نۀ به د خفګان ښکاره کولو په وجه خپل سرونه د هغوئ دپاره ګنجى کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18230, 'Jeremiah 16:7', 'Jeremiah', 16, 7, '&nbsp;هيڅوک به هغوئ ته د غمرازۍ روټۍ نۀ راوړى، تر دې چې د خپل مور او پلار دپاره به تعزيت نۀ کوى، او نۀ به ورته څوک د تسلۍ دپاره څښلو له څۀ ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18231, 'Jeremiah 16:8', 'Jeremiah', 16, 8, '&nbsp;او هغه کور ته هم مۀ ورننوځه په کوم کور کښې چې د خوراک څښاک پروګرام وى او د هغوئ سره روټۍ ته مۀ کښېنه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18232, 'Jeremiah 16:9', 'Jeremiah', 16, 9, '&nbsp;ځکه چې دا مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ درته فرمائى، ستا په ژوند کښې او ستا د سترګو د وړاندې به زۀ په دې مُلک کښې د خندا او د خوشحالۍ آوازونه ختم کړم. نور به په کښې د ناوې او زلمى د خوشحالۍ آوازونه نۀ اورېدلے کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18233, 'Jeremiah 16:10', 'Jeremiah', 16, 10, '&nbsp;کله چې تۀ هغوئ ته دا هر څۀ ووائې نو هغوئ به درنه تپوس وکړى چې، مالِک خُدائ په مونږ دومره سخت افت ولې نازلوى؟ مونږ څۀ غلطى کړې ده؟ مونږ داسې کومه ګناه د مالِک خُدائ خلاف کړې ده؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18234, 'Jeremiah 16:11', 'Jeremiah', 16, 11, '&nbsp;نو بيا هغوئ ته ووايه چې، مالِک خُدائ فرمائى چې، ستاسو پلار نيکۀ زۀ هېر کړے وم، هغوئ زما په ځائ د نورو معبودانو عبادت او خِدمت وکړو. او هغوئ زۀ پرېښودم او زما د کلام تابعدارى يې ونۀ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18235, 'Jeremiah 16:12', 'Jeremiah', 16, 12, '&nbsp;خو تاسو د خپل پلار نيکۀ نه هم زيات بد سلوک وکړو. ګوره چې څنګه تاسو هر يو زما د پيروى په ځائ د خپلو سرکشه او بدکاره زړونو خواهشاتو ته غوږ ونيولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18236, 'Jeremiah 16:13', 'Jeremiah', 16, 13, '&nbsp;نو زۀ به تاسو د دې مُلک نه داسې مُلک ته وشړم چې نۀ يې تاسو ته څۀ پته شته او نۀ يې ستاسو پلار نيکۀ ته څۀ پته وه، نو هلته به تاسو شپه او ورځ د نورو معبودانو عبادت کوئ، ځکه چې زۀ به په تاسو نور رحم نۀ کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18237, 'Jeremiah 16:14', 'Jeremiah', 16, 14, '&nbsp;مالِک خُدائ وفرمائيل چې، ”داسې وخت راروان دے چې خلق به داسې قسم نۀ خورى چې، د ژوندى خُدائ پاک په نوم مې دې قسم وى چا چې بنى اِسرائيل د مِصر نه راوويستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18238, 'Jeremiah 16:15', 'Jeremiah', 16, 15, '&nbsp;خو هغوئ به داسې قسم خورى چې، د ژوندى خُدائ پاک په نوم مې دې قسم وى چا چې بنى اِسرائيل د شمال او د هغه ټولو مُلکونو نه راوويستل کومو ته چې هغۀ شړلى وُو. ځکه چې زۀ به هغوئ دوباره هغه مُلک ته واپس راولم کوم چې ما د هغوئ پلار نيکۀ له ورکړے وو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18239, 'Jeremiah 16:16', 'Jeremiah', 16, 16, '&nbsp;مالِک خُدائ فرمائى چې، ”بلکې زۀ به اوس ډېر ماهيګر درولېږم چې هغوئ به دوئ راونيسى. او د دې نه وروستو به زۀ ډېر ښکاريان درولېږم او دوئ به هغوئ په هر يو غر، غونډۍ او د ګټانو د غارونو نه ښکار کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18240, 'Jeremiah 16:17', 'Jeremiah', 16, 17, '&nbsp;د هغوئ ټول عملونه زما د سترګو د وړاندې دى او زۀ يې وينم، هغه زما نه پټ نۀ دى، او تر دې چې د هغوئ ګناهونه هم زما د سترګو نه پټ پناه نۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18241, 'Jeremiah 16:18', 'Jeremiah', 16, 18, '&nbsp;زۀ به هغوئ له د خپلو ګناهونو او حرامو کارونو بدله يو په دوه ورکړم، ځکه چې هغوئ د بې‌ساه شکلونو او نفرت آميزه بُتانو په وجه زما موروثى مُلک پليت کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18242, 'Jeremiah 16:19', 'Jeremiah', 16, 19, '&nbsp;اے مالِکه خُدايه، تۀ زما طاقت او زما قلعه يې، د مصيبت په وخت کښې زما پناه ګاه يې. د دُنيا د آخر سر نه به قومونه تا ته راشى او وائى به چې، ”زمونږ پلار نيکۀ سره هيڅ نۀ وو بلکې دروغژن معبودان، هغه بې‌کاره بُتان چې دوئ ته هيڅ قسمه ښېګړه نۀ شى ورکولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18243, 'Jeremiah 16:20', 'Jeremiah', 16, 20, '&nbsp;خلق خو ځان له خپل خُدايان په خپله جوړوى، خو په حقيقت کښې هغه صحيح خُدايان نۀ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18244, 'Jeremiah 16:21', 'Jeremiah', 16, 21, '&nbsp;”نو په دې وجه به زۀ هغوئ ته په دې وخت کښې د خپل زور او طاقت په حقله تعليم ورکړم. نو بيا به هغوئ په دې باندې پوهه شى چې زما نوم مالِک خُدائ دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18245, 'Jeremiah 17:1', 'Jeremiah', 17, 1, '&nbsp;مالِک خُدائ فرمائى چې، ”د يهوداه د خلقو ګناه د اوسپنې په قلم چې نوکه يې د هيرې ده، ستاسو د کاڼو نه په سختو زړُونو نقش شوې ده او ستاسو د قربان‌ګاه په ګوټونو ليکلې شوې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18246, 'Jeremiah 17:2', 'Jeremiah', 17, 2, '&nbsp;نۀ صرف تاسو بلکې ستاسو بچى هم خپلې قربان‌ګاه او د اشيرې بُت شکلونه همېشه رايادوى کۀ د شنې ونې په خوا کښې وى او کۀ په اوچته غونډۍ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18247, 'Jeremiah 17:3', 'Jeremiah', 17, 3, '&nbsp;نو زۀ به په دې مُلک کښې خپل مقدس غر سره ستاسو د ټول مال دولت او ستاسو علاقائى عبادتخانې نورو خلقو ته د غنيمت په توګه حواله کړم، دا ستاسو د ګناهونو بدل دے کوم چې تاسو په خپل ټول مُلک کښې کړې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18248, 'Jeremiah 17:4', 'Jeremiah', 17, 4, '&nbsp;ستاسو د خپلې ګناه په وجه به هغه مُلک ستاسو د لاس نه ووځى کوم چې ما تاسو ته په ميراث کښې درکړے دے. زۀ به تاسو په هغه مُلکونو کښې چې تاسو يې نۀ پېژنئ دشمنانو ته د غلام په شکل حواله کړم. ځکه چې تاسو زما د غصې اور بل کړے دے او هغه به تل بليږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18249, 'Jeremiah 17:5', 'Jeremiah', 17, 5, '&nbsp;مالِک خُدائ فرمائى چې، ”لعنت دې په هغه چا وى چې د هغۀ زړۀ د مالِک خُدائ نه اوړېدلے وى او په فانى انسان توکل او د هغۀ په زور بهروسه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18250, 'Jeremiah 17:6', 'Jeremiah', 17, 6, '&nbsp;هغه د بيابان د هغه بوټى په شان دے، کۀ څۀ هم چې خير وى خو هغوئ ته به مِلاو نۀ شى. ځکه چې هغه به د بيابان په خشکه او مالګينه زمکه کښې شوے وى، چرته چې نور څۀ نۀ کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18251, 'Jeremiah 17:7', 'Jeremiah', 17, 7, '&nbsp;خو بختور دى هغوئ څوک چې په مالِک خُدائ يقين لرى، او په مالِک خُدائ يې توکل کړے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18252, 'Jeremiah 17:8', 'Jeremiah', 17, 8, '&nbsp;هغوئ د هغه ونو په شان دى چې د لختى په غاړه کَرلے شوې وى او جرړې يې اوبو ته رسېدلې وى. نو کله چې د ګرمۍ موسم راشى نو يره يې نۀ وى، د هغوئ پاڼې هر وخت شنې وى. او په خُشک سالۍ کښې يې څۀ پرېشانى نۀ وى، نو کله هم بې‌مېوې نۀ پاتې کيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18253, 'Jeremiah 17:9', 'Jeremiah', 17, 9, '&nbsp;د انسان زړۀ د هر څۀ نه زيات دوکه مار وى، او د شرارت نه ډک وى. څوک پرې هم نۀ پوهيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18254, 'Jeremiah 17:10', 'Jeremiah', 17, 10, '&nbsp;”زۀ مالِک خُدائ د انسان د زړۀ لټون کوم او د هغۀ پټ سوچونه آزمائيم، زۀ هر چا ته اجر د هغۀ د عمل په مطابق ورکوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18255, 'Jeremiah 17:11', 'Jeremiah', 17, 11, '&nbsp;هغه څوک چې په ناجائزه طريقې سره مال دولت راجمع کړى هغه د هغه تيتر په شان وى چې پردۍ هګۍ وشاربى کومې چې هغې اچولې نۀ وى، نو وروستو به د هغۀ نه ټول مال دولت لاړ شى، کله چې د هغۀ عمر نيم تېر شى نو د هغۀ مال دولت به د هغۀ نه والوځى او په آخر کښې به دے خپل ځان کم عقل ثابت کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18256, 'Jeremiah 17:12', 'Jeremiah', 17, 12, '&nbsp;خو هغه جلالى تخت چې د ازل نه اوچت دے، هغه زمونږ د خُدائ پاک مقدس کور دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18257, 'Jeremiah 17:13', 'Jeremiah', 17, 13, '&nbsp;اے مالِکه خُدايه، د بنى اِسرائيلو اُميده، هر څوک چې تا نه مخ واړوى هغوئ ټول به ټيټ سترګې او شرمنده شى. هغوئ چا چې تا نه مخ اړولے دے په دوړو د ليکلو په شان دى، دوئ به زر ختم شى ځکه چې هغوئ د هغه مالِک خُدائ نه مخ اړولے دے څوک چې د ژوندون د اوبو چينه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18258, 'Jeremiah 17:14', 'Jeremiah', 17, 14, '&nbsp;اے مالِکه خُدايه، کۀ چرې تۀ ما له شفا راکړې نو زۀ به بلکل روغ رمټ شم، کۀ چرې تۀ ما له خلاصون راکړې نو زۀ به بچ شم، ځکه چې زۀ صرف ستا ثناء صِفت کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18259, 'Jeremiah 17:15', 'Jeremiah', 17, 15, '&nbsp;هغوئ ما ته بار بار دا وائى چې، د مالِک خُدائ هغه کارونه څۀ شول د چا د پوره کېدلو په حقله چې هغۀ پېشګوئې کړې وه؟ نو اوس دې هغه پوره کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18260, 'Jeremiah 17:16', 'Jeremiah', 17, 16, '&nbsp;اے مالِکه خُدايه، زۀ د هغه کار نه نۀ يم تښتېدلے د کوم دپاره چې تاسو زۀ د خپل قوم دپاره د شپونکى په حيثيت مقرر کړے يم. تاسو ته پته ده چې ما په هغوئ د افت د ورځې د راتلو خواهش نۀ دے کړے. زما د شونډو نه چې څۀ هم وتلى دى هغه ستا په وړاندې څرګند دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18261, 'Jeremiah 17:17', 'Jeremiah', 17, 17, '&nbsp;مالِکه خُدايه، ما مۀ يروه، د افت په ورځ صرف تۀ زما اُميد يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18262, 'Jeremiah 17:18', 'Jeremiah', 17, 18, '&nbsp;زما دشمنان دې وشرميږى خو ما مۀ شرموه، په هغوئ يره راوله خو ما مۀ يروه. په هغوئ د افت ورځې راوله، او هغوئ په دوه چنده تباه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18263, 'Jeremiah 17:19', 'Jeremiah', 17, 19, '&nbsp;مالِک خُدائ ما ته وفرمائيل، ”يرمياه، لاړ شه او د عوامى دروازې په خولۀ کښې ودرېږه په کومه چې د يهوداه بادشاهان ځى راځى او هم داسې د يروشلم په نورو دروازو کښې ودرېږه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18264, 'Jeremiah 17:20', 'Jeremiah', 17, 20, '&nbsp;هغوئ ته ووايه، د مالِک خُدائ پېغام واورئ. اے د يهوداه بادشاهانو او د يهوداه ټولو خلقو او د يروشلم اوسېدونکو او هغوئ ټولو ته چې په دې دروازې ځى راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18265, 'Jeremiah 17:21', 'Jeremiah', 17, 21, '&nbsp;مالِک خُدائ فرمائى چې، خبردار چې د سبت په ورځ په خپل سر پنډ مۀ اوچتوئ او د يروشلم په دروازو پنډ سره مۀ ننوځئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18266, 'Jeremiah 17:22', 'Jeremiah', 17, 22, '&nbsp;او تر دې چې په خپلو کورونو کښې هم د سبت په ورځ هيڅ قسمه کار مۀ کوئ او مۀ څۀ بار اوچتوئ. خو د سبت ورځ مقدسه وساتئ لکه څنګه چې ما ستاسو پلار نيکۀ ته حکم کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18267, 'Jeremiah 17:23', 'Jeremiah', 17, 23, '&nbsp;خو هغوئ ما ته غوږ ونۀ نيولو او نۀ يې ما ته توجو راکړه او نۀ يې زما پيروى وکړه. خو هغوئ سرکشه وُو او اصلاح کولو ته يې جواب ورنۀ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18268, 'Jeremiah 17:24', 'Jeremiah', 17, 24, '&nbsp;خو مالِک خُدائ فرمائى، کۀ چرې تاسو زما خبره ومنئ او د سبت په ورځ په دې دروازو د تجارت دپاره څۀ داخل نۀ کړئ او نۀ څۀ کار وکړئ، او هغه مقدسه وساتئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18269, 'Jeremiah 17:25', 'Jeremiah', 17, 25, '&nbsp;نو بيا به هغه بادشاهان څوک چې د داؤد په تخت ناست دى نو هغوئ به د خپلو آفسرانو سره د دې ښار په دروازو ځى راځى. او هغوئ او د هغوئ آفسران به په آسونو او ګاډو سوارۀ راشى، او د يهوداه خلق به ورسره وى او هغوئ څوک چې په يروشلم کښې اوسيږى، او دا ښار به د تل دپاره آباد وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18270, 'Jeremiah 17:26', 'Jeremiah', 17, 26, '&nbsp;د يهوداه د ښارونو او د يروشلم د ګېرچاپېره کلو نه به خلق راشى، هغوئ به د بنيامين د علاقې، د مغربى غونډو د لمنو نه، او د نجب او د غريزې علاقې نه به د خپلو سوزېدونکو نذرانو او قربانو سره راشى. هغوئ به د خپلو غلو دانو او خوشبوئى د شکرانې نذرانې سره د مالِک خُدائ کور ته راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18271, 'Jeremiah 17:27', 'Jeremiah', 17, 27, '&nbsp;خو کۀ تاسو زما خبره ونۀ منئ او د سبت ورځ مقدسه ونۀ ساتئ، او لکه د نورو ورځو په شان د سبت په ورځ د سودا پنډونه د يروشلم دروازو ته راؤړئ، نو بيا به زۀ په دې دروازو اور بل کړم. او دا اور به د يروشلم محلونه وسوزوى. او د دې اور لمبې به هيڅوک مړې کولے نۀ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18272, 'Jeremiah 18:1', 'Jeremiah', 18, 1, '&nbsp;مالِک خُدائ ما يرمياه له پېغام راکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18273, 'Jeremiah 18:2', 'Jeremiah', 18, 2, '&nbsp;”لاندې د کُلال کور ته لاړ شه، نو هلته به زۀ تا له خپل پېغام درکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18274, 'Jeremiah 18:3', 'Jeremiah', 18, 3, '&nbsp;نو زۀ هلته د کُلال کور ته لاړم او ما هغه وليدو چې په خپله څرخه يې کار کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18275, 'Jeremiah 18:4', 'Jeremiah', 18, 4, '&nbsp;خو چې کوم لوښے به هغۀ د خټې نه جوړولو نو هغه به په لاس کښې هغه شان نۀ راتلو کوم به چې د هغۀ اُميد وو نو بيا به يې هغه خراب کړو او بل څيز به يې ترې نه جوړول شروع کړل کوم به چې هغۀ ته ښۀ ښکارېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18276, 'Jeremiah 18:5', 'Jeremiah', 18, 5, '&nbsp;بيا مالِک خُدائ ما له دا پېغام راکړو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18277, 'Jeremiah 18:6', 'Jeremiah', 18, 6, '&nbsp;”اے بنى اِسرائيلو، نو زۀ دا نۀ شم کولے چې تاسو سره هغه کار وکړم کوم به چې کُلال د خټې سره کولو؟ لکه څنګه چې خټه د کُلال په لاس کښې وه، داسې تاسو زما په لاس کښې يئ. دا د مالِک خُدائ فرمان دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18278, 'Jeremiah 18:7', 'Jeremiah', 18, 7, '&nbsp;هرکله کۀ چرې زۀ وغواړم چې يو قوم يا بادشاهت د بېخ نه ختم کړم، يا هغه راوغورزوم او تباه يې کړم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18279, 'Jeremiah 18:8', 'Jeremiah', 18, 8, '&nbsp;او کۀ چرې هغه قوم کوم ته چې ما خبردارے ورکړے وى، د خپلو بدو عملونو نه راوګرځى، نو بيا به زۀ نرمۍ نه کار واخلم او د خپلې ارادې نه به واپس شم او په هغوئ به هغه افت نۀ راولم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18280, 'Jeremiah 18:9', 'Jeremiah', 18, 9, '&nbsp;او کۀ بل وخت کښې زۀ چرې دا ووايم چې زۀ به دا قوم يا يو بادشاهت آباد او قائم کړم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18281, 'Jeremiah 18:10', 'Jeremiah', 18, 10, '&nbsp;خو کۀ بيا هغه مُلک زما په وړاندې شرارت کوى او زما تابعدارى ونۀ کړى نو زۀ به د هغه ښۀ کولو اراده پرېږدم د کوم چې ما د هغوئ دپاره اراده کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18282, 'Jeremiah 18:11', 'Jeremiah', 18, 11, '&nbsp;نو اوس زما د طرفه د يهوداه او يروشلم خلقو ته ووايه چې مالِک خُدائ فرمائى چې ګورئ، زۀ په تاسو د افت راوستلو تيارے کوم او ستاسو خلاف منصوبه جوړوم. نو هر يو دې د خپلو بدو طريقو نه راواوړى، او هغه څۀ دې کوى کوم چې ښۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18283, 'Jeremiah 18:12', 'Jeremiah', 18, 12, '&nbsp;خو هغوئ په جواب کښې ووئيل چې، خپله خولۀ دې په مونږ مۀ خرابوه، مونږ چې په کومو طريقو اوسېدل غواړُو هغه شان به اوسيږو، په سرکشۍ سره به د خپل زړۀ بد خواهشونه پوره کوُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18284, 'Jeremiah 18:13', 'Jeremiah', 18, 13, '&nbsp;”نو په دې وجه مالِک خُدائ فرمائى چې، د نورو قومونو د خلقو نه دا تپوس وکړه چې کله هم هغوئ د داسې کار په حقله اورېدلى دى. بنى اِسرائيل دې د پاکې پېغلې په شان وى، خو هغې ډېر بد کار وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18285, 'Jeremiah 18:14', 'Jeremiah', 18, 14, '&nbsp;آيا د لبنان د غرونو د څوکو نه کله هم واوره ويلې شوې او ختمه شوې ده څۀ؟ آيا د هغوئ د غريزه او لرې چينو يخې اوبۀ بهېدل کله ختم شوى دى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18286, 'Jeremiah 18:15', 'Jeremiah', 18, 15, '&nbsp;بلکې زما خلقو زۀ هېر کړے يم، او هغوئ بې‌کاره بُتانو ته خوشبويۍ وسوزولې، بُتان کوم چې د هغوئ د تيندک باعث شُو او دوئ يې د پخوانو ښو لويو لارو نه جدا کړل او په کچه لارو باندې روان شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18287, 'Jeremiah 18:16', 'Jeremiah', 18, 16, '&nbsp;نو په دې وجه به د هغوئ مُلک په بيابان بدل کړے شى او نورو ته به د خندا ذريعه وګرځى. څوک هم چې په دې لاره تېريږى نو هغوئ به حق حيران شى او د يهوداه په حالت به يې د يرې نه وېښتۀ نيغ ودريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18288, 'Jeremiah 18:17', 'Jeremiah', 18, 17, '&nbsp;نو زۀ به لکه د نمرخاتۀ د باد په شان هغوئ د دشمنانو په وړاندې خوارۀ وارۀ کړم. او د هغوئ د مصيبت په ورځ به زۀ خپل مخ د هغوئ نه واړوم او د هغوئ فريادونه به نۀ اورم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18289, 'Jeremiah 18:18', 'Jeremiah', 18, 18, '&nbsp;نو بيا خلقو ووئيل، ”راځئ چې د يرمياه خلاف منصوبه جوړه کړُو. ځکه چې مونږ سره ډېر اِمامان، هوښياران او نبيان شته دے. مونږ ته د هغۀ د شريعت د تعليم، نصيحت او پېشګويۍ ورکولو ضرورت نشته دے. راځئ چې په خولۀ د هغۀ په حقله افواګانې خورې کړُو او په هغۀ اِلزام ولګوو او دوئ چې څۀ هم وائى نور ورته غوږ ونۀ نيسو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18290, 'Jeremiah 18:19', 'Jeremiah', 18, 19, '&nbsp;نو بيا ما ووئيل چې، ”اے مالِکه خُدايه، ما ته غوږ ونيسه او زما دشمنان چې زما خلاف څۀ وائى په هغې غور وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18291, 'Jeremiah 18:20', 'Jeremiah', 18, 20, '&nbsp;ولې هغوئ د ښو بدله په بدو سره ورکوى څۀ؟ اوس خو هغوئ زما د وژلو دپاره کنده کنستلې ده. هغه وخت راياد کړه چې زۀ به ستا په حضور کښې ودرېدم او د هغوئ سفارش به مې تاسو ته کولو چې په هغوئ باندې خپل قهر او غضب مۀ نازلوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18292, 'Jeremiah 18:21', 'Jeremiah', 18, 21, '&nbsp;خو اے مالِکه خُدايه، اوس پرېږده چې د هغوئ بچى د لوږې نه مړۀ شى، پرېږده چې هغوئ په تُوره قتل کړے شى. د هغوئ ښځې دې بورې او کونډې شى، پرېږده چې د هغوئ بوډاګان سړى په وبا مړۀ شى، پرېږده چې د هغوئ ځوانان په جنګ مړۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18293, 'Jeremiah 18:22', 'Jeremiah', 18, 22, '&nbsp;پرېږده چې ناګهانه په هغوئ جنګى سپاهيان ورننوځى، او د هغوئ د کورونو نه دې چغې او سورې واورېدلے شى. ځکه چې هغوئ زما دپاره کنده کنستلې ده او پټ دام يې راته خور کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18294, 'Jeremiah 18:23', 'Jeremiah', 18, 23, '&nbsp;خو اے مالِکه خُدايه، تۀ د هغوئ په ټولو منصوبو باندې پوهه يې چې زما د وژلو دپاره يې تيارې کړې دى. تۀ د هغوئ جرم مۀ معاف کوه او مۀ د هغوئ ګناه د خپلو سترګو نه اخوا کوه. پرېږده چې هغوئ ستا په وړاندې راوغورزيږى، او په خپل قهر او غضب کښې هغوئ له سزا ورکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18295, 'Jeremiah 19:1', 'Jeremiah', 19, 1, '&nbsp;مالِک خُدائ ما ته وفرمائيل چې، ”لاړ شه او د کُلال نه يو د خټو منګے په بيعه واخله. او ځان سره د خلقو يو څو مشران او لوئ اِمامان بوځه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18296, 'Jeremiah 19:2', 'Jeremiah', 19, 2, '&nbsp;او د بنى‌هنوم وادۍ ته لاړ شه، او د کُلالانو د ماتو لوښو دروازې ته مخامخ هلته هغه پېغام خلقو ته بيان کړه کوم چې زۀ تا له درکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18297, 'Jeremiah 19:3', 'Jeremiah', 19, 3, '&nbsp;مالِک خُدائ ما ته وفرمائيل چې هغوئ ته داسې ووايه، اے د يهوداه بادشاهانو او د يروشلم خلقو، مالِک خُدائ، ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې زۀ به په دې ځائ دومره سخت افت راولم، او چې څوک يې هم واورى نو د هغۀ غوږونه به وبوګنيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18298, 'Jeremiah 19:4', 'Jeremiah', 19, 4, '&nbsp;ځکه چې زۀ هغوئ پرېښے يم او دا ځائ يې غېرو معبودانو ته حواله کړو، او په دې ځائ کښې هغوئ هغه معبودانو ته داسې قربانۍ پېش کړې چې هغه نۀ دوئ په خپله او نۀ د دوئ پلار نيکۀ او نۀ د يهوداه بادشاهانو پخوا کړى وى. هغوئ دا زمکه د بې‌ګناه خلقو په وينو تويولو سره ډکه او رنګ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18299, 'Jeremiah 19:5', 'Jeremiah', 19, 5, '&nbsp;او هغوئ د بعل بُت دپاره علاقائى عبادتخانې جوړې کړې دى چې خپل بچى هلته په کښې د سوزېدونکى قربانۍ په توګه بعل بُت ته پېش کړى. د داسې کار ما نۀ هغوئ ته حکم ورکړے دے او نۀ مې په خيال خاطر کښې راغلى دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18300, 'Jeremiah 19:6', 'Jeremiah', 19, 6, '&nbsp;نو مالِک خُدائ فرمائى چې خبردار، هغه وخت راروان دے چې خلق به نور دې ځائ ته د ”توفت“ يا بنى‌هنوم وادى ونۀ وائى، بلکې دا به ”د قتل و غارت د وادۍ“ په نوم مشهوره شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');